import{_ as l}from"./chunks/硬件架构.CBEg5olg.js";import{c as o,Q as e,j as r,m as a}from"./chunks/framework.DOi4mjdC.js";const p="/assets/NPU%E6%9E%B6%E6%9E%84%E7%89%88%E6%9C%AC220%E9%AB%98%E7%BB%B4%E5%88%87%E5%88%86.BVYLTdGr.png",g="/assets/%E6%9C%AC%E6%9E%B6%E6%9E%84%E7%89%88%E6%9C%AC%E9%AB%98%E7%BB%B4%E5%88%87%E5%88%86.BDTTQHRA.png",i="/assets/%E6%9C%AC%E6%9E%B6%E6%9E%84%E7%89%88%E6%9C%ACUB-bank%E7%A4%BA%E6%84%8F%E5%9B%BE.BbOjivcW.png",s="/assets/loop_normal.DikxBD7y.png",n="/assets/forloop.BHeswXXf.png",u="/assets/loop_normal.DikxBD7y.png",d="/assets/loop_comact.cgGGTiy-.png",c="/assets/Fixpipe_int8-channel_merge.CPrebIX1.png",q="/assets/Fixpipe_int4_channel_merge.Bmc8OS0u.png",f="/assets/Fixpipe_F32_channel_split.DwQVcY5_.png",C="/assets/1b2.DVnmXk48.png",I="/assets/0000000-%E6%A0%B8%E5%86%85%E5%90%8C%E6%AD%A5%E6%9C%80%E7%BB%88%E7%89%88.DNZ8FLgV.png",B="/assets/%E6%A0%B8%E9%97%B4%E5%90%8C%E6%AD%A5.kxUGe11U.png",A="/assets/new_%E6%A0%B8%E9%97%B4%E5%90%8C%E6%AD%A5.BUEDZB0M.png",v=JSON.parse('{"title":"NPU架构版本3510","description":"","frontmatter":{},"headers":[{"level":1,"title":"NPU架构版本3510","slug":"npu架构版本3510"},{"level":2,"title":"硬件架构图","slug":"硬件架构图"},{"level":2,"title":"计算单元","slug":"计算单元"},{"level":2,"title":"存储单元","slug":"存储单元"},{"level":2,"title":"搬运单元","slug":"搬运单元"},{"level":2,"title":"AIC AIV核间通信","slug":"aic-aiv核间通信"},{"level":2,"title":"同步控制","slug":"同步控制"}],"relativePath":"guide/编程指南/高级编程/硬件实现/架构规格/NPU架构版本3510.md","filePath":"guide/编程指南/高级编程/硬件实现/架构规格/NPU架构版本3510.md"}'),h={name:"guide/编程指南/高级编程/硬件实现/架构规格/NPU架构版本3510.md"};function b(m,t,_,S,E,F){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="npu架构版本3510" tabindex="-1">NPU架构版本3510 <a class="header-anchor" href="#npu架构版本3510" aria-label="Permalink to &quot;NPU架构版本3510&quot;">​</a></h1><p>本节介绍__NPU_ARCH__版本号为<a href="./../../../语言扩展层/SIMD-BuiltIn关键字.html#table65291052154114">3510</a>的硬件架构和其功能说明。</p><h2 id="硬件架构图" tabindex="-1">硬件架构图 <a class="header-anchor" href="#硬件架构图" aria-label="Permalink to &quot;硬件架构图&quot;">​</a></h2><p>如下图所示，本架构中AI Core分为AIC和AIV两个独立的核，分别用于矩阵计算和向量计算。AIC核与AIV核配比为1：2。每个核都有自己的Scalar单元，能独立加载自己的代码段。</p><p><img src="'+l+'" alt=""></p><p>该架构的关键特点有：</p><ul><li><p>增加L0C Buffer -&gt; Unified Buffer、Unified Buffer &lt;-&gt; L1 Buffer的数据通路。</p></li><li><p>删除Global Memory -&gt; L0A Buffer、Global Memory -&gt; L0B Buffer的数据通路。</p></li><li><p>删除L1 Buffer-&gt; Global Memory的数据通路。</p></li><li><p>SSBuffer，用于AIC和AIV的核间通信。</p></li><li><p>增加SIMD Register File存储层次，在SIMD程序中，数据从Unified Buffer搬运到Register进行计算，产生的中间结果可以不用传回Unified Buffer，直接在寄存器计算。</p></li><li><p>新增SIMT相关硬件单元。SIMT相关硬件单元介绍如下：</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.85%&quot;&gt;&lt;p&gt;SIMT硬件单元名称&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.15%&quot;&gt;&lt;p&gt;说明&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.85%&quot;&gt;&lt;p&gt;SIMT DCache&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.15%&quot;&gt;&lt;p&gt;SIMT访问GM需要经过SIMT DCache中转，SIMT支持最大128KB Data Cache，Data Cache直接复用UB作为cacheline，SIMT所有对外访存都是以128B为粒度。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.85%&quot;&gt;&lt;p&gt;Warp Scheduler&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.15%&quot;&gt;&lt;p&gt;实现硬件的多线程调度。&lt;/p&gt; &lt;p&gt;SIMT每个AIV有4个Warp Scheduler。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.85%&quot;&gt;&lt;p&gt;SIMT Register File&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.15%&quot;&gt;&lt;p&gt;为SIMT应用程序提供的总容量为128KB的超大容量寄存器。每个Thread可用的寄存器数和Thread数量有关，对应关系为：&lt;/p&gt; &lt;ul&gt;&lt;li&gt;1025~2048条Thread：16个Register。&lt;/li&gt;&lt;li&gt;513~1024条Thread：32个Register。&lt;/li&gt;&lt;li&gt;257~512条Thread：64个Register。&lt;/li&gt;&lt;li&gt;1~256条Thread：127个Register。&lt;/li&gt;&lt;/ul&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li></ul><h2 id="计算单元" tabindex="-1">计算单元 <a class="header-anchor" href="#计算单元" aria-label="Permalink to &quot;计算单元&quot;">​</a></h2><p><strong>Cube计算单元和Vector计算单元分离部署</strong></p><p>本架构中，Cube计算单元和Vector计算单元分别部署在AIC核和AIV核上，每个核都有自己的Scalar单元，能独立加载自己的代码段。</p><p><strong>Vector计算单元</strong></p><ul><li><p>Vector计算单元支持U8、U16、U32、S8、S16、S32、BF16、FP16、FP32数据类型。</p></li><li><p>Vector计算单元每拍可处理256字节的数据。</p></li><li><p>Vector计算单元处理的数据来源来自于Register。</p></li><li><p>在本架构版本中，高维切分接口中的传入的掩码值会被转化为MaskReg传入Vector计算单元，而在<a href="./../../../语言扩展层/SIMD-BuiltIn关键字.html#table65291052154114">NPU架构版本2201</a>中，掩码值从特殊的掩码寄存器中读取。</p><p><strong>图 1</strong> NPU架构版本220高维切分<br><img src="'+p+'" alt="" title="NPU架构版本220高维切分"></p><p><strong>图 2</strong> 本架构版本高维切分<br><img src="'+g+'" alt="" title="本架构版本高维切分"></p></li></ul><p><strong>Cube计算单元</strong></p><ul><li>Cube计算单元支持FP32/FP16/BF16/HiF8/FP8_E4M3/U8/S8。 一拍完成一个float16数据类型的16x16与16x16大小的矩阵乘；如果是int8_t数据类型，则一拍完成16*32与32*16大小的矩阵乘。</li><li>Cube计算单元可以访问的存储单元有L0A Buffer、L0B Buffer、L0C Buffer，其中L0A Buffer存储左矩阵，L0B Buffer存储右矩阵，L0C Buffer存储矩阵乘的结果和中间结果。</li></ul><p><strong>Scalar单元</strong></p><ul><li>Scalar单元支持U16/S16/U32/S32/U64/S64/FP64数据类型。</li><li>在Regbase架构中，Aux Scalar计算单元单独处理SIMD_VF函数内的Scalar计算，Scalar计算单元处理SIMD_VF函数外的Scalar计算。</li></ul><h2 id="存储单元" tabindex="-1">存储单元 <a class="header-anchor" href="#存储单元" aria-label="Permalink to &quot;存储单元&quot;">​</a></h2><p><strong>获取存储单元的内存空间大小</strong></p><p>开发者可以通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E5%B9%B3%E5%8F%B0%E4%BF%A1%E6%81%AF%E8%8E%B7%E5%8F%96.md" target="_blank" rel="noreferrer">平台信息获取</a>接口查询各存储单元的内存空间大小。</p><p><strong>各存储单元的最小访问粒度（对齐要求）</strong></p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;7.5200000000000005%&quot;&gt;&lt;p&gt;核&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.22%&quot;&gt;&lt;p&gt;存储单元&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.26%&quot;&gt;&lt;p&gt;对齐要求&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;7.5200000000000005%&quot;&gt;&lt;p&gt;AIV&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.22%&quot;&gt;&lt;p&gt;&lt;span&gt;Unified Buffer&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.26%&quot;&gt;&lt;p&gt;32Byte对齐。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; rowspan=&quot;6&quot; valign=&quot;top&quot; width=&quot;7.5200000000000005%&quot;&gt;&lt;p&gt;AIC&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.22%&quot;&gt;&lt;p&gt;&lt;span&gt;L1 Buffer&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.26%&quot;&gt;&lt;p&gt;32Byte对齐。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;&lt;span&gt;L0A Buffer&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;512Byte对齐。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;&lt;span&gt;L0B Buffer&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;512Byte对齐。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;&lt;span&gt;L0C Buffer&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;64Byte对齐。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;BiasTable Buffer&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;64Byte对齐。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;Fixpipe Buffer&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;64Byte对齐。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p><strong>各存储单元推荐使用的数据排布格式</strong></p><ul><li><p>L0A Buffer、L0B Buffer和L0C Buffer推荐分别采用以下分形格式：</p><ul><li>L0A Buffer：FRACTAL_NZ（由于硬件结构变更，本架构下L0A Buffer的分形改为NZ）</li><li>L0B Buffer：FRACTAL_ZN</li><li>L0C Buffer：FRACTAL_NZ</li></ul><p>这些格式针对矩阵乘法等计算密集型任务进行优化，可显著提升计算效率。</p></li><li><p>L1 Buffer缓存推荐使用FRACTAL_NZ格式。当L1 Buffer采用NZ格式时，数据搬运到L0A/L0B Buffer（需分别转换为ZN格式）时，可降低格式转换开销。</p></li><li><p>Unified Buffer对数据格式没有要求。</p></li></ul><p><strong>存储单元的访问冲突</strong></p><p>本NPU架构版本UB结构如下图所示，当多个操作尝试同时访问Unified Buffer同一个bank或者bank group时，可能会发生bank冲突，包括读写冲突、写写冲突、读读冲突，这种冲突会导致访问排队，降低性能。在NPU架构版本2201中，同一个bank group只有一组读口和写口，最多一拍完成一读或者一写，在本NPU架构版本中每个bank group有两组读口和写口，最多同时允许2读0写或者1读1写。相关读写约束如下：</p><ul><li><strong>读写冲突</strong>：读操作和写操作同时尝试访问同一个bank。</li><li><strong>写写冲突</strong>：多个写操作同时尝试访问同一个bank group。</li><li><strong>读读冲突</strong>：两个读操作同时尝试访问同一个bank，或者两个以上读操作同时尝试访问同一个bank group。</li></ul><p><strong>图 3</strong> 本架构版本UB bank示意图<br><img src="'+i+'" alt="" title="本架构版本UB-bank示意图"></p><p><strong>Register寄存器</strong></p><ul><li><p>RegTensor</p><p>RegTensor用于存放Reg矢量计算数据， RegTensor位宽为VL（Vector Length, 256字节）。</p></li><li><p>MaskReg</p><p>MaskReg用于指示在计算过程中哪些元素参与计算，宽度为RegTensor的八分之一（VL/8）。</p></li><li><p>UnalignRegForLoad &amp; UnalignRegForStore</p><p>UnalignRegForLoad、UnalignRegForStore用作缓冲区来优化UB和RegTensor之间连续不对齐地址访问的开销。在读不对齐地址前，UnalignRegForLoad、UnalignRegForStore应该通过LoadUnAlignPre API初始化，然后使用LoadUnAlign API。在写不对齐地址时，先使用StoreUnAlign API，再使用StoreUnAlignPost API后处理。</p></li><li><p>AddrReg</p><p>AddrReg即为Address Register（地址寄存器），是用于存储地址偏移量的寄存器。AddrReg应该通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/AddrReg.md" target="_blank" rel="noreferrer">CreateAddrReg</a>初始化，然后在循环之中使用AddrReg存储地址偏移量。AddrReg每层循环中根据所设置的stride进行自增。</p></li></ul><h2 id="搬运单元" tabindex="-1">搬运单元 <a class="header-anchor" href="#搬运单元" aria-label="Permalink to &quot;搬运单元&quot;">​</a></h2><p><strong>搬运时的对齐要求</strong></p><p>由于搬运后的数据用于参与数据计算，因此对搬运数据大小有要求，搬运到Unified Buffer的数据大小需要按照DataBlock对齐，其余存储单元的数据搬运必须按<a href="./../../../../技术附录/概念原理和术语/神经网络和算子/数据排布格式.html">分形要求</a>进行搬运。例如，数据从L1 Buffer搬运到L0A Buffer时，数据格式需要从NZ转换为ZN格式，搬运数据的大小要按分形大小对齐，如果L1 Buffer的剩余大小不足1个分形，则硬件执行中会出现异常。</p><p><strong>MTE硬通道</strong></p><ul><li>AIV新增Unified Buffer和L1 Buffer之间的硬通道。</li><li>新增支持GM到Unified Buffer搬运和Unified Buffer到GM搬运的Loop模式。在Loop模式下，每次循环可以是Normal模式或Compact模式，Normal模式和Compact模式可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DataCopyPad(ISASI).md" target="_blank" rel="noreferrer">DataCopyPad(ISASI)</a>。 <ul><li><p>单次Loop以Normal模式搬运</p><p>若单个数据块长度为32B对齐，则无需插入Padding，可通过多次Repeat搬运多组数据块。</p><p><img src="'+s+'" alt=""></p><p>若单个数据块长度不为32B对齐，则需在每个数据块后插入Padding，使其32B对齐后再进行搬运。</p><p><img src="'+n+'" alt=""></p></li><li><p>单次Loop以Compact模式搬运</p><p>Compact可以一次搬运一组数据块，当这些数据块的总长度为32B对齐的时候，则无需在最后插入Padding。</p><p><img src="'+u+'" alt=""></p><p>当一组数据块的长度不是32B对齐，需要在这组数据块后插入padding，使总长度32B对齐。</p><p><img src="'+d+'" alt=""></p></li></ul></li></ul><p><strong>支持Fixpipe硬件化加速</strong></p><p>Fixpipe是NPU将典型操作进行硬化的加速模块，位于AIC内部，配合Cube计算单元完成随路计算，主要功能如下：</p><ul><li>量化反量化：包括S4/S8/S32/FP16/FP32/FP8_E4M3/HiF8/BF16。</li><li>Relu功能，包括ReLu、PReLu和Leaky ReLu等典型的激活函数。</li><li>数据格式转换，包括： <ul><li>通过Channel merge、Channel split可以实现分形大小的转换，保证输出到L1 Buffer/GM的分形满足诉求。</li><li>支持L0C Source的NZ2ND、NZ2DN随路转换。</li></ul></li></ul><p>Channel merge支持S8、U8、S4和U4数据类型，而Channel split支持FP32数据类型。</p><ul><li><p>Channel merge（S8和U8数据类型）</p><p>对于转换为S8或U8的目标数据类型，分形矩阵通过硬件从16x16转换为16x32，如果输出通道数N是16的偶数倍，则N方向上每2个相邻的16x16分形矩阵将合并为1个16x32分形矩阵。如果N是16的奇数倍，则将通道1到通道（N–16）合并，最后16个通道保持未合并。</p><p>如下所示，目标数据类型为S8，M为32，N为48，首先将前2列16x16分形矩阵合并为一个16x32矩阵，然后将剩余的16x16分形矩阵直接移入L1 Buffer。</p><p><img src="'+c+'" alt=""></p></li><li><p>Channel merge（S4和U4数据类型）：</p><p>对于转换为S4或U4的目标数据类型，分形矩阵通过硬件从16x16转换为16x64，如果输出通道数N是64的倍数，则N方向上每4个相邻的16x16分形矩阵将合并为1个单个的16x64分形矩阵。</p><p>例如，这里目标数据类型为S4，M为32，N为64，首先将第1行16x16分形矩阵合并为一个16x64矩阵，然后将第2行16x16分形矩阵也合并。</p><p>在这种情况下，N的配置必须是64的倍数。</p><p><img src="'+q+'" alt=""></p></li><li><p>FP32 Channel split：</p><p>对于目标类型为FP32，分形矩阵可以通过硬件从16x16转换为16x8，如果使能Channel split，则每个16x16分形矩阵将被分裂为2个16x8分形矩阵。</p><p>如下图所示，这里的目标数据类型是FP32，M是64，N是32，它将被拆分为16个16x8的分形。</p><p><img src="'+f+'" alt=""></p></li></ul><h2 id="aic-aiv核间通信" tabindex="-1">AIC AIV核间通信 <a class="header-anchor" href="#aic-aiv核间通信" aria-label="Permalink to &quot;AIC AIV核间通信&quot;">​</a></h2><p>该架构支持AIC: AIV为1:1和1:2的核间通信，核间通信通过SSBuf进行，这一点和NPU220架构有所不同，NPU220架构中核间通信通过GM来完成。</p><p><img src="'+C+'" alt=""></p><h2 id="同步控制" tabindex="-1">同步控制 <a class="header-anchor" href="#同步控制" aria-label="Permalink to &quot;同步控制&quot;">​</a></h2><ul><li><p>核内同步</p><p>由于AI Core内部的执行单元（如MTE2搬运单元、Vector计算单元等）以异步并行的方式运行，在读写Local Memory（如Unified Buffer）时可能存在数据依赖关系。为确保数据一致性及计算正确性，需通过同步控制协调操作时序。</p><p>以MTE2从GM搬运数据至UB，进行Vector计算单元的Abs计算，再搬运回GM的流程为例，需满足以下同步条件：</p><ol><li><p>数据搬运与计算顺序</p><ul><li>GM→UB搬运完成后再启动Vector单元的Abs计算（避免计算时未完成搬运导致的数据缺失）；</li><li>Vector计算完成后再执行UB→GM的数据搬运（确保结果数据已就绪）。</li></ul></li><li><p>循环搬运计算场景的同步规则</p><ul><li>前序计算完成后再启动新搬运：上一次计算未完成时，不得触发新数据搬运（防止UB中旧数据被覆盖）；</li><li>前序数据搬出完成后再启动新计算：上一次数据未完全从UB搬出时，不得触发新计算任务（避免目标内存区域的覆盖冲突）。</li></ul></li></ol><p>同步控制流程如下图所示：</p><p><img src="'+I+'" alt=""></p><p>上图中，ID1、ID2、ID3、ID4、ID5、ID6表示事件ID（EventID），每个EventID对应一块存储数据的搬运状态，确保数据操作的正确性和一致性。</p><p>需要注意以下几点：</p><ul><li><p>建议通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/AllocEventID.md" target="_blank" rel="noreferrer">AllocEventID</a>或者<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/FetchEventID.md" target="_blank" rel="noreferrer">FetchEventID</a>接口获取EventID，以确保其合法性和有效性。</p></li><li><p>EventID的数量有限，使用后应立即调用ReleaseEventID释放资源，避免EventID耗尽，影响系统正常运行。</p></li><li><p>SetFlag和WaitFlag必须成对使用，且SetFlag和WaitFlag的参数必须完全一致（包括模板参数和事件ID）。如果不匹配，可能导致当前核的计算异常，或影响下一个核的算子执行，引发timeout问题。</p><p>例如，<code>SetFlag&lt;HardEvent::S_MTE3&gt;(1)</code>和<code>SetFlag&lt;HardEvent::MTE3_MTE1&gt;(1)</code>设置的不是同一个EventID，因为其模板参数不同。只有当模板参数和事件ID完全一致时，才表示同一个EventID。</p></li><li><p>不允许连续设置同一个EventID，因为这可能导致事件状态混乱或未被正确处理。</p></li><li><p>不建议手动插入TEventID，不能手动插入6和7的TEventID，因为它们可能被系统预留或用于特殊用途。</p></li></ul></li><li><p>核间同步</p><p>当不同核之间操作同一块全局内存时，可能存在读后写、写后读以及写后写等数据依赖问题，需要进行核间同步控制。</p><p>核间同步控制分为以下几种模式，如下图所示：</p><ul><li>模式0：AI Core核间的同步控制。对于AIC场景，同步所有的AIC核，直到所有的AIC核都执行到CrossCoreSetFlag时，CrossCoreWaitFlag后续的指令才会执行；对于AIV场景，同步所有的AIV核，直到所有的AIV核都执行到CrossCoreSetFlag时，CrossCoreWaitFlag后续的指令才会执行。</li><li>模式1：AI Core内部，AIV核之间的同步控制。如果两个AIV核都运行了CrossCoreSetFlag，CrossCoreWaitFlag后续的指令才会执行。</li><li>模式2：AI Core内部，AIC与AIV之间的同步控制（1:2）。在AIC核执行CrossCoreSetFlag之后， 两个AIV上CrossCoreWaitFlag后续的指令才会继续执行；两个AIV都执行CrossCoreSetFlag后，AIC上CrossCoreWaitFlag后续的指令才能执行。</li><li>模式4：AI Core内部，AIC与AIV之间的同步控制（1:1）。AIV0与AIV1可单独触发AIC等待。比如，在AIC核执行CrossCoreSetFlag之后， AIV0上CrossCoreWaitFlag后续的指令才会继续执行；AIV0执行CrossCoreSetFlag后，AIC上CrossCoreWaitFlag后续的指令才能执行。</li></ul><p><img src="'+B+'" alt=""></p><p>例如，在AIC中将L0C的计算结果搬运到GM后，AIV需要将GM的数据搬运到UB。此时，可以使用CrossCoreSetFlag和CrossCoreWaitFlag命令，确保数据从L0C成功搬运到GM后，再从GM搬运到UB，流程如下图所示。</p><p><img src="'+A+'" alt=""></p><p><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/CrossCoreSetFlag(ISASI).md" target="_blank" rel="noreferrer">CrossCoreSetFlag</a>和<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/CrossCoreWaitFlag(ISASI).md" target="_blank" rel="noreferrer">CrossCoreWaitFlag</a>接口配合使用。使用时需传入核间同步的标记ID(flagId)，即上图中的ID1，每个ID对应一个初始值为0的计数器。执行CrossCoreSetFlag后ID对应的计数器增加1；执行CrossCoreWaitFlag时如果对应的计数器数值为0则阻塞不执行；如果对应的计数器大于0，则计数器减一，同时后续指令开始执行。flagId取值范围是0-10。</p><p>需要注意以下几点：</p><ul><li><p><strong>成对使用</strong></p><p>CrossCoreSetFlag和CrossCoreWaitFlag必须成对使用，否则可能导致算子超时问题。</p></li><li><p><strong>一致性要求</strong></p><p>CrossCoreSetFlag 的模板参数和flagId必须与CrossCoreWaitFlag完全一致，否则视为不同的flagId。例如，CrossCoreSetFlag&lt;0x0, PIPE_MTE3&gt;(0x8) 和 CrossCoreSetFlag&lt;0x2, PIPE_FIX&gt;(0x8) 设置的不是同一个flagId。</p></li><li><p><strong>避免连续设置</strong></p><p>不允许连续设置同一个flagId，以防止计数器状态混乱。</p></li><li><p><strong>与高阶 API 的使用冲突</strong></p><p>Matmul高阶API内部实现中使用了本接口进行核间同步控制，所以不建议开发者同时使用该接口和Matmul高阶API，否则会有flagId冲突的风险。</p></li><li><p><strong>计数器限制</strong></p><p>同一flagId的计数器最多可以设置15次。</p></li><li><p><strong>默认流水类型</strong></p><p>CrossCoreWaitFlag不需要显式设置指令所在的流水类型，默认使用PIPE_S。</p></li></ul></li></ul>',44)])])}const L=o(h,[["render",b]]);export{v as __pageData,L as default};
